$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$script:Checks = 0
$root = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))

function Read-Source([string]$RelativePath) {
    return [IO.File]::ReadAllText((Join-Path $root $RelativePath))
}

function Require-Match([string]$Text, [string]$Pattern, [string]$Message) {
    $script:Checks++
    if ($Text -notmatch $Pattern) { throw $Message }
}

function Reject-Match([string]$Text, [string]$Pattern, [string]$Message) {
    $script:Checks++
    if ($Text -match $Pattern) { throw $Message }
}

$window = Read-Source 'Editor/Development/DevelopmentBootstrapWindow.cs'
$createEnvironment = Read-Source 'Editor/Development/WindowsDevelopmentInitializationEnvironment.cs'
$existingEnvironment = Read-Source 'Editor/Development/ExistingPackageSetAcquisition.cs'
$prepareCommand = Read-Source 'Editor/Development/UseExistingPackageSetPrepareCommand.cs'
$bootstrapIo = Read-Source 'Editor/Development/DevelopmentBootstrapIO.cs'
$documents = Read-Source 'Editor/Development/DevelopmentBootstrapDocuments.cs'
$configuration = Read-Source 'Editor/Development/PackageSetProjectConfiguration.cs'
$composition = Read-Source 'Editor/PackageManagementSourceComposition.cs'
$strictJson = Read-Source 'Editor/Development/StrictJsonDocument.cs'
$strictBindingShape = Read-Source 'Editor/Development/StrictBindingJsonShape.cs'
$apply = Read-Source 'Tools/ApplyDevelopmentBootstrap.ps1'
$readme = Read-Source 'README.md'
$development = Read-Source 'docs/DEVELOPMENT_INITIALIZATION.md'
$production = $window + "`n" + $createEnvironment + "`n" + $existingEnvironment + "`n" + $prepareCommand
$publicSurface = $production + "`n" + $readme + "`n" + $development

Require-Match $window '"Create PackageSet"\s*,\s*"Use Existing PackageSet"' 'The UI must expose exactly Create PackageSet and Use Existing PackageSet.'
Require-Match $window 'new PackageSetCreator\(' 'Create PackageSet must use PackageSetCreator.'
Require-Match $window 'new ProjectPackageSetConverter\(' 'Use Existing PackageSet must use ProjectPackageSetConverter.'
Require-Match $window 'new CreatePackageSetRequest\(' 'The Create UI must build the Create-only request.'
Require-Match $window 'new UseExistingPackageSetRequest\(' 'The Existing UI must build the Existing-only request.'
Require-Match $window 'TextField\("PackageSet repository", repository\)' 'Use Existing does not expose a transient repository input for an unconfigured Project.'
Require-Match $window 'TextField\("Exact revision", resolvedRevision\)' 'Use Existing does not expose a transient exact-revision input.'
Require-Match $window 'TextField\("Tracking ref", trackingRef\)' 'Use Existing does not expose a transient tracking-ref input.'
Require-Match $window 'TextField\("New PackageSet repository", createRepository\)' 'Create does not expose its own transient PackageSet repository input.'
Require-Match $window 'ObservedRepository|SourceRepository' 'The review surface must expose per-entry source repository authority.'
Reject-Match $publicSurface 'RestoreExistingPackageSet|AttachExistingPackageSet|CreatePackageSetFromProject' 'Legacy three-mode product names remain.'
Reject-Match $production 'DevelopmentInitializationMode|DevelopmentInitializationRequest|ProjectDevelopmentInitializer' 'Legacy workflow API remains in production.'
Reject-Match $window 'SaveLocal\(' 'Prepare must not persist local checkout state before Apply.'
if (Test-Path (Join-Path $root 'Editor/Development/ExistingPackageSetAttachment.cs')) { throw 'Legacy Attachment filename remains.' }
$script:Checks++

Require-Match $prepareCommand 'public static class UseExistingPackageSetPrepareCommand' 'The Unity batchmode Prepare entrypoint is missing.'
Require-Match $prepareCommand 'public static void Run\(\)' 'The Unity -executeMethod target must be public and static.'
Require-Match $prepareCommand '"--pm-package-set-root"' 'The batchmode Prepare command is missing its PackageSet checkout argument.'
Require-Match $prepareCommand '"--pm-prepare-output"' 'The batchmode Prepare command is missing its result argument.'
Require-Match $prepareCommand 'PackageSetProjectConfiguration\.LoadProject\(' 'The batchmode command must read Project PackageSet authority.'
Require-Match $prepareCommand 'PackageSetAcquisitionStrategy\.OpenLocalCheckout' 'The batchmode command must use the reviewed local checkout.'
Require-Match $prepareCommand 'new WindowsUseExistingPackageSetEnvironment\(' 'The batchmode command must use the production Existing environment.'
Require-Match $prepareCommand 'new ProjectPackageSetConverter\(' 'The batchmode command must use the production Existing application service.'
Require-Match $prepareCommand 'converter\.Prepare\(' 'The batchmode command must execute production Prepare.'
Require-Match $prepareCommand 'EditorApplication\.Exit\(1\)' 'The batchmode command must return a non-zero exit on failure.'
Require-Match $prepareCommand 'RequirePrivateOutputPath\(' 'The batchmode result must not write an unignored Project worktree path.'
Reject-Match $prepareCommand 'OfflineApplyDocument|UseExistingPackageSetPlan\(' 'The batchmode command must not construct an offline plan itself.'

Require-Match $createEnvironment 'class WindowsCreatePackageSetEnvironment\s*:\s*ICreatePackageSetEnvironment' 'Create environment port is missing.'
Require-Match $existingEnvironment 'class WindowsUseExistingPackageSetEnvironment\s*:\s*IUseExistingPackageSetEnvironment' 'Use Existing environment port is missing.'
Require-Match $createEnvironment 'ObservedCreatePackageSetSource ObserveSelection\(' 'Create source repository observation is missing.'
Require-Match $existingEnvironment 'AuthoritativePackageSetEntry\(identity, sourcePath, projectionPath, sourceRepository, exactSourceRevision' 'Existing authority must include source repository and exact revision.'
Require-Match $existingEnvironment 'new ObservedPackageSetEntry\(originalRelative, sourceRepository, observation\)' 'Existing Project mapping must report observed source repository.'
Require-Match $existingEnvironment 'PackageSetModeObservation ObservePackageSetMode\(' 'Use Existing typed PackageSet-mode observation is missing.'
Require-Match $existingEnvironment 'ObservedProjectPackageSetBinding' 'Project binding is not observed as typed authority.'
Require-Match $existingEnvironment 'ObservedRuntimeBindings' 'Runtime bindings are not observed as typed authority.'
Require-Match $existingEnvironment 'StrictBindingJsonShape\.ValidateProject' 'Project binding observation does not use strict raw JSON shape validation.'
Require-Match $existingEnvironment 'StrictBindingJsonShape\.ValidateRuntime' 'Runtime binding observation does not use strict raw JSON shape validation.'
Require-Match $strictJson 'Duplicate object member' 'Strict JSON parsing does not reject duplicate members.'
Require-Match $strictBindingShape 'contains unknown member' 'Strict binding parsing does not reject unknown members.'
Require-Match $existingEnvironment 'ObserveIndexFile\(' 'Durable binding observation does not include Project Git index evidence.'
Require-Match $existingEnvironment 'OrdinaryProjectionIndexMatches\(' 'Existing projection observation does not verify ordinary Project index blobs.'
Require-Match $existingEnvironment 'IndexGitlinkMatches\(' 'Existing bootstrap observation does not verify the exact Project index gitlink.'
Require-Match $existingEnvironment 'matchingSections == 1' 'Bootstrap observation does not reject duplicate .gitmodules sections for one path.'
Require-Match $existingEnvironment 'ContainsGitOwnership\(canonical\)' 'PhysicalSnapshot observation does not reject undeclared nested Git ownership.'
Require-Match $existingEnvironment 'if \(state == DevelopmentProjectionState\.Absent\)[\s\S]{0,500}?HasRelatedProjectSubmodule\(' 'Absent observation does not reject a related legacy Project submodule.'
Require-Match $existingEnvironment 'Use Existing PackageSet requires a portable gitlink-backed source' 'Existing LocalDraft rejection is missing.'
Require-Match $existingEnvironment 'VerifyAuthorityEvidence\(' 'Existing manifest/gitlink authority must be fingerprinted.'
Require-Match $existingEnvironment 'FindBootstrapSourcePath\(' 'Bootstrap mapping must be derived from declared source evidence.'
Reject-Match $existingEnvironment 'File\.WriteAllText|File\.AppendAllText|\"commit\"|\"submodule\"\s*,\s*\"add\"' 'Use Existing contains a PackageSet write/commit path.'
Reject-Match $production 'ReconcileRestoredLayout|ReconcileManagedProjection|RetargetManagedJunction' 'Prepare-time reconciliation remains.'
Reject-Match $production 'Directory\.Delete\(|File\.Move\(' 'Production Prepare must not relocate or delete Project paths.'

Require-Match $existingEnvironment 'DevelopmentProjectionState\.Absent' 'Absent projection observation is missing.'
Require-Match $createEnvironment 'DevelopmentProjectionState\.PhysicalSnapshot' 'PhysicalSnapshot projection observation is missing.'
Require-Match $existingEnvironment 'DevelopmentProjectionState\.BootstrapGitlink' 'BootstrapGitlink projection observation is missing.'
Require-Match $existingEnvironment 'DevelopmentProjectionState\.CorrectJunction' 'CorrectJunction projection observation is missing.'
Require-Match $createEnvironment 'CreateProjectEvidence\(' 'Project Prepare invariants are not fingerprinted.'
Require-Match $createEnvironment 'RequireUnchangedProject|ObserveProject' 'Project observation support is missing.'
Require-Match $createEnvironment 'verifiedEvidenceToken' 'Project observation does not verify a stable evidence snapshot.'
Require-Match $createEnvironment 'AuditOperationJournals\(' 'Workflow validation does not stop for recovery journals.'
Require-Match $createEnvironment 'AppendOperationJournalEvidence\(' 'Final Project evidence does not cover operation-journal races.'
Require-Match $createEnvironment 'DurablePathOccupied\(journalPath\)' 'Operation journal audit does not detect a directory or reparse occupant at journal.json.'
Reject-Match $createEnvironment 'File\.Exists\(journalPath\)' 'Operation journal audit still treats non-file journal occupants as absent.'
Require-Match $createEnvironment 'Path\.Combine\(operationPath, "apply\.lock"\)' 'Operation journal audit does not block an active Apply lease.'
Require-Match $createEnvironment 'bool validated = status\.Equals\("validated"[\s\S]{0,500}?bool safe = validated \|\| applied \|\| rolledBack \|\| preflightFailed;[\s\S]{0,100}?if \(safe\) return' 'A validated pre-mutation journal is not accepted as safe workflow evidence.'
Require-Match $createEnvironment 'bool legacyShape = journal\.Members\.Count == 5;[\s\S]{0,300}?bool directoriesValid = JournalMemberHasKind\(journal, "directories", StrictJsonValueKind\.Array\);[\s\S]{0,300}?bool currentShape = journal\.Members\.Count == 6 && directoriesValid;[\s\S]{0,300}?if \(!legacyShape && !currentShape\) return false;' 'Unity journal audit does not accept the exact legacy and current helper journal schemas.'
Require-Match $createEnvironment 'status"?, "--porcelain=v2"?, "--untracked-files=all"?' 'Project validation does not require a fully clean tracked and untracked baseline.'
Require-Match $bootstrapIo 'GIT_OPTIONAL_LOCKS' 'Read-only Git observation may refresh and rewrite the Project index.'
Reject-Match $createEnvironment 'private string gitRoot|private string gitDirectory' 'Create Observe retains mutable Project Git context.'
Reject-Match $existingEnvironment 'private string gitRoot|private string gitDirectory' 'Use Existing Observe retains mutable Project Git context.'
Require-Match $existingEnvironment 'RequireOnlyIgnoredMetadata\(' 'Existing source observation does not reject ignored non-authoritative content.'

Require-Match $documents 'class OfflineApplyDocument[\s\S]*?schemaVersion = 2' 'Offline plan schema must be 2.'
Require-Match $documents 'public string projectionState = string\.Empty' 'Offline projectionState field is missing.'
Require-Match $documents 'public string sourceRepository = string\.Empty' 'Offline source repository authority is missing.'
Require-Match $documents 'public string observedRepository = string\.Empty' 'Offline observed repository evidence is missing.'
Require-Match $documents 'public string exactPin = string\.Empty' 'Offline exact source pin is missing.'
Require-Match $documents 'public string projectBindingHash = string\.Empty' 'Offline plan does not bind the observed Project binding fingerprint.'
Require-Match $documents 'public string runtimeBindingsHash = string\.Empty' 'Offline plan does not bind the observed runtime binding fingerprint.'
Reject-Match $documents 'alreadyEnabled' 'Legacy alreadyEnabled plan field remains.'
Require-Match $documents 'class LocalPackageSetStateDocument[\s\S]*?schemaVersion = 1[\s\S]*?checkoutPath' 'C# local checkout schema is not version 1 + checkoutPath.'
Require-Match $apply 'schemaVersion = 1; checkoutPath = \$p\.packageSetRoot' 'Apply local checkout schema does not round-trip with C#.'
Require-Match $apply "projectionState -notin @\('Absent','PhysicalSnapshot','BootstrapGitlink','CorrectJunction'\)" 'Apply does not enforce the schema-2 projection state set.'
Require-Match $apply 'Repository-Identity' 'Offline preflight does not canonicalize source repository identity.'
Require-Match $apply '\$sourceRepository -cne \$observedRepository' 'Offline preflight does not compare authoritative and observed repositories exactly.'
Require-Match $apply '\$sourceHead, \[string\]\$entry\.exactPin' 'Offline preflight does not require source HEAD to match the exact pin.'
Require-Match $apply 'Check-DurableHash \$projectBindingPath \$p\.projectBindingHash' 'Offline preflight does not independently verify the observed Project binding fingerprint.'
Require-Match $apply 'Check-DurableHash \$runtimeBindingsPath \$p\.runtimeBindingsHash' 'Offline preflight does not independently verify the observed runtime binding fingerprint.'
Require-Match $apply 'Audit-SiblingOperations' 'Offline preflight does not stop for sibling recovery journals.'
Require-Match $apply 'ready\.sha256' 'Offline Apply does not require a finalized successful-Prepare marker.'
Require-Match $apply 'Generated \.csproj metadata is not ignored through the final Project projection' 'Offline Apply does not verify paired metadata ignore behavior after Junction cutover.'
Require-Match $existingEnvironment 'ObserveIndexFile\(projectGitRoot, relative, regularFile, "100644"' 'Binding index observation does not require an ordinary non-executable JSON blob.'
Require-Match $apply '\$ReopenUnity -and \$ExitCode -eq 0 -and \$Committed -and \$null -ne \$p' 'A failed or rolled-back Apply may reopen Unity against an unsafe Project state.'
Require-Match $apply 'function Backup-BytesCore[\s\S]{0,1800}?FileMode\]::Open, \[IO\.FileAccess\]::ReadWrite, \[IO\.FileShare\]::None' 'Canonical source metadata writes do not use an exclusive compare-and-write handle.'
Require-Match $apply 'function Copy-MovedMetaToProjection[\s\S]{0,700}?FileShare\]::None[\s\S]{0,500}?Backup-CheckedBytes' 'Projection-root metadata is not copied from exclusively held immutable evidence.'
Require-Match $apply 'function Remove-GitConfigSectionTransactional[\s\S]{0,1000}?FileMode\]::Open, \[IO\.FileAccess\]::ReadWrite, \[IO\.FileShare\]::None[\s\S]{0,1000}?previousHash -cne \$requiredHash' '.gitmodules mutation does not use an exclusive compare-and-write handle.'
Require-Match $apply 'function Ensure-JournaledOrdinaryDirectory[\s\S]{0,1800}?owned = \$false[\s\S]{0,500}?\$Directories\.Add\([\s\S]{0,700}?CreateDirectory[\s\S]{0,500}?owned = \$true' 'Helper-created parent directories are not journaled as owned rollback state.'
Require-Match $apply 'function Remove-OwnedDirectoryRecord[\s\S]{0,800}?Require-DeclaredMutationPath[\s\S]{0,800}?Require-OrdinaryDirectory[\s\S]{0,800}?\$isEmpty' 'Rollback does not remove only empty, helper-owned ordinary directories.'
Require-Match $apply 'function Remove-RollbackLink[\s\S]{0,800}?Within \$p\.projectGitRoot[\s\S]{0,800}?Within \$p\.packageSetRoot[\s\S]{0,800}?Is-CorrectJunction' 'Rollback Junction removal does not revalidate its declared path and target.'
Require-Match $apply 'function Restore-MoveRecord[\s\S]{0,900}?Require-OwnedBackupPath[\s\S]{0,900}?Require-UnoccupiedPath \$original[\s\S]{0,900}?Require-OrdinaryDirectory \$backupPath' 'Rollback move restoration does not fail closed on destination occupancy or unsafe backup paths.'
Require-Match $apply 'GetAttributes\(\$unityLock\)[\s\S]{0,900}?Directory -bor \[IO\.FileAttributes\]::ReparsePoint[\s\S]{0,500}?Unity lockfile path is occupied by a non-file or reparse point' 'UnityLockfile validation does not fail closed for directory or reparse occupants.'
Require-Match $configuration 'LoadProject\([\s\S]{0,700}?TryReadDurableDocument[\s\S]{0,700}?StrictBindingJsonShape\.ValidateProject' 'Project binding loading bypasses the durable strict JSON consumer.'
Require-Match $configuration 'LoadLocal\([\s\S]{0,700}?TryReadDurableDocument[\s\S]{0,700}?StrictBindingJsonShape\.ValidateLocalCheckout' 'Local checkout loading bypasses the durable strict JSON consumer.'
Require-Match $existingEnvironment 'ObserveProjectBinding\([\s\S]{0,1800}?OpenDurableFileSnapshot[\s\S]{0,1800}?StrictBindingJsonShape\.ValidateProject' 'Project binding observation bypasses its shared durable strict snapshot.'
Require-Match $existingEnvironment 'ObserveRuntimeBindings\([\s\S]{0,1800}?OpenDurableFileSnapshot[\s\S]{0,1800}?StrictBindingJsonShape\.ValidateRuntime' 'Runtime binding observation bypasses its shared durable strict snapshot.'
Require-Match $composition "ReadDurableHandoff[\s\S]{0,1200}?text\[0\] == '\\uFEFF'[\s\S]{0,300}?text\.Substring\(1\)" 'Durable handoff JSON does not remove a single leading UTF-8 encoding signature before strict parsing and deserialization.'
Require-Match $composition 'ReadBootstrap[\s\S]{0,1000}?string json = ReadDurableHandoff\([\s\S]{0,300}?StrictJsonDocument\.Parse\(json\)[\s\S]{0,300}?JsonUtility\.FromJson<BootstrapPlanDocument>\(json\)' 'Bootstrap handoff strict parsing and deserialization do not share the same normalized JSON text.'
Reject-Match $createEnvironment "strictUtf8\.GetString\(bytes\)[\s\S]{0,300}?\\uFEFF" 'The shared durable snapshot decoder must not globally accept a JSON encoding signature.'
Require-Match $createEnvironment 'ReadOrdinaryHeadFileEvidence\([\s\S]{0,1800}?ls-tree[\s\S]{0,1200}?ordinaryBlob[\s\S]{0,1200}?hash-object", "--no-filters"' 'PackageSet manifest authority is not tied to an exact ordinary HEAD blob and mode.'
Require-Match $apply '\$expectedSourceTree = \[string\]\$file\.mode \+ '' blob '' \+ \[string\]\$file\.sourceBlob[\s\S]{0,300}?\+ \$filePath[\s\S]{0,300}?\$sourceTreeEntry -cne \$expectedSourceTree' 'Offline Apply does not require each ordinary source file to match its exact planned HEAD mode, blob, and path.'
Require-Match $apply 'Tracked generated \.csproj metadata exclusion no longer matches source HEAD mode, blob, and path' 'Offline Apply does not preserve exact HEAD authority for a tracked paired .csproj.meta exclusion.'
Require-Match $existingEnvironment 'CaptureAuthorityEvidence\([\s\S]{0,900}?ReadOrdinaryHeadFileEvidence\(checkout, "package-set\.json"\)[\s\S]{0,500}?ReadOrdinaryHeadFileEvidence\(checkout, "\.gitmodules"\)' 'Use Existing does not capture exact HEAD authority for manifest and .gitmodules.'
Require-Match $existingEnvironment 'ValidateTargetRepository\([\s\S]{0,900}?target repository is required[\s\S]{0,900}?Project origin repository identity is required[\s\S]{0,900}?targetIdentity\.Equals\(projectIdentity' 'Use Existing does not require PackageSet target.repository to match the Project origin.'
Require-Match $createEnvironment 'ReadGitmodules\([\s\S]{0,1800}?keysBySection\.ContainsKey\(currentSection\)[\s\S]{0,300}?duplicate section' '.gitmodules parsing does not reject duplicate submodule sections.'
Require-Match $createEnvironment 'RequirePackageSetOwnedCheckout\([\s\S]{0,1400}?IsIndependentGitCheckout[\s\S]{0,1400}?Within\(packageSetGitDirectory, sourceGitDirectory\)' 'Canonical source checkout Git metadata is not required to belong to the PackageSet.'
Require-Match $existingEnvironment 'RequirePackageSetOwnedCheckout\(checkout, source, entry\.identity\)' 'Use Existing does not apply PackageSet ownership validation to canonical checkouts.'
Require-Match $createEnvironment 'if \(placement\.Kind == DevelopmentSourceKind\.LocalDraft\)[\s\S]{0,6500}?DevelopmentSourceObservation observation = new DevelopmentSourceObservation\([^\r\n]*DevelopmentProjectionState\.BootstrapGitlink' 'Create PackageSet does not preserve GitSubmodule selections as BootstrapGitlink state.'
Require-Match $createEnvironment 'RequireAssetsProjectionRoot\([\s\S]{0,500}?StartsWith\("Assets/"[\s\S]{0,500}?ordinary child of Assets' 'Managed projection roots are not restricted to an Assets child.'
Require-Match $createEnvironment 'generatedProjectMetadata[\s\S]{0,600}?companionExcluded[\s\S]{0,800}?ProjectIgnoredGeneratedCsprojMetadata' 'Tracked paired .csproj.meta files are not carried into the approved exclusion set.'
Require-Match $prepareCommand 'insidePackageSet[\s\S]{0,300}?insidePackageSetGitDirectory[\s\S]{0,500}?outside the Project and authoritative PackageSet Git trees' 'Prepare output is not rejected inside the authoritative PackageSet tree.'
Require-Match $prepareCommand 'DurablePathOccupied\(outputPath\)[\s\S]{0,700}?FileMode\.CreateNew, FileAccess\.Write, FileShare\.None' 'Prepare output is not created exclusively after an unoccupied-path check.'
Reject-Match $apply '(?-i:\$backup\s*=)' 'A case-insensitive local $backup variable shadows the script-scoped $Backup recovery root.'
Require-Match $createEnvironment 'MarkReady\(' 'Prepare does not finalize an audited offline plan.'
Require-Match $createEnvironment 'MarkReady\([\s\S]{0,800}?IO\.NoReparseAncestors\(planPath\)[\s\S]{0,800}?WriteNewOperationText\(readyPath, planHash\)' 'Ready finalization does not validate the plan path and create a protected marker.'
Require-Match $createEnvironment 'new FileStream\(path, FileMode\.CreateNew, FileAccess\.Write, FileShare\.None\)' 'Operation evidence files are not created exclusively.'
Require-Match $development 'StrictJson\.Contracts\\StrictJson\.Contracts\.csproj' 'Development validation docs omit the strict JSON contract command.'
Reject-Match $createEnvironment 'schemaVersion != 1 && document\.schemaVersion != 2|projectionName : entry\.projectionPath|string\.IsNullOrWhiteSpace\(value\).*GitSubmodule' 'Existing manifest authority still accepts a legacy schema or fallback.'
Reject-Match $configuration 'LegacyProjectPackageSetDocument|schemaVersion\s*==\s*(1|2)' 'Project PackageSet configuration still accepts a legacy schema fallback.'
Reject-Match $configuration '\.Any\s*\(' 'Project PackageSet configuration still uses a lambda-based revision check.'

$newSources = $window + "`n" + $createEnvironment + "`n" + $existingEnvironment + "`n" + $prepareCommand + "`n" + $configuration
Reject-Match $newSources '\bvar\s+[A-Za-z_]' 'New C# uses var.'
Reject-Match $newSources '=>' 'New C# uses an expression-bodied member or lambda.'
Reject-Match $newSources '(?m)^\s*(public|private|internal|protected)[^\r\n]*\(\s*$' 'A method signature was split before its parameters.'

Write-Host ("PASS: {0} Unity Package Management V2 workflow surface contracts" -f $script:Checks)
